const input = $json.body || $json;

const CLINIC_ID = '00000000-0000-0000-0000-000000000101';

function text(value) {
  return String(value ?? '').trim();
}

function digitsOnly(value) {
  return String(value ?? '').replace(/\D/g, '');
}

function normalizePhone(value) {
  let digits = digitsOnly(value);

  if (digits.startsWith('0') && digits.length >= 9) {
    digits = '595' + digits.slice(1);
  }

  if (digits.length === 9 && digits.startsWith('9')) {
    digits = '595' + digits;
  }

  return {
    phone: digits || null,
    phone_plus: digits ? `+${digits}` : null,
  };
}

function scoreTreatment(value) {
  const v = text(value).toLowerCase();
  if (v.includes('implante')) return 40;
  if (v.includes('dolor') || v.includes('urgencia')) return 35;
  if (v.includes('ortodoncia') || v.includes('bracket')) return 25;
  if (v.includes('blanqueamiento')) return 15;
  if (v.includes('limpieza')) return 10;
  if (v.includes('consulta')) return 5;
  return 5;
}

function scoreUrgency(value) {
  const v = text(value).toLowerCase();
  if (v.includes('hoy')) return 35;
  if (v.includes('semana')) return 25;
  if (v.includes('mes')) return 10;
  if (v.includes('consultando') || v.includes('investigando')) return -10;
  return 0;
}

function scoreEvaluation(value) {
  const v = text(value).toLowerCase();
  if (v.includes('radiografía') || v.includes('radiografia') || v.includes('estudio')) return 20;
  if (v === 'sí' || v === 'si') return 15;
  if (v === 'no') return 5;
  return 0;
}

function scoreSituation(value) {
  const v = text(value).toLowerCase();
  if (v.includes('agendar')) return 30;
  if (v.includes('dolor') || v.includes('molestia')) return 25;
  if (v.includes('precio')) return 5;
  if (v.includes('comparando')) return -10;
  return 0;
}

function classify(score) {
  if (score >= 80) return 'Lead Caliente';
  if (score >= 45) return 'Lead Medio';
  return 'Lead Frío';
}

function nextAction(classification) {
  if (classification === 'Lead Caliente') return 'Contactar inmediatamente';
  if (classification === 'Lead Medio') return 'Contactar hoy';
  return 'Seguimiento automático';
}

function nextFollowupISO(classification, baseDate) {
  const d = new Date(baseDate);
  if (classification === 'Lead Caliente') d.setHours(d.getHours() + 2);
  else if (classification === 'Lead Medio') d.setDate(d.getDate() + 1);
  else d.setDate(d.getDate() + 3);
  return d.toISOString();
}

function estimateValue(treatment) {
  const t = text(treatment).toLowerCase();
  if (t.includes('implante')) return 5000000;
  if (t.includes('ortodoncia') || t.includes('bracket')) return 4000000;
  if (t.includes('blanqueamiento')) return 500000;
  if (t.includes('limpieza')) return 250000;
  if (t.includes('carilla')) return 2000000;
  if (t.includes('dolor') || t.includes('urgencia')) return 350000;
  return 250000;
}

function buildWhatsappLink(phoneDigits, name, treatment) {
  if (!phoneDigits) return null;
  const message = `Hola ${name || ''}, vimos que dejaste tus datos por ${treatment || 'una consulta dental'}. ¿Querés que te pasemos los horarios disponibles para una evaluación?`;
  return `https://wa.me/${phoneDigits}?text=${encodeURIComponent(message)}`;
}

const name = text(input.nombre || input.name);
const phoneRaw = text(input.telefono || input.phone || input.phone_plus);
const treatment = text(input.tratamiento || input.treatment);
const urgency = text(input.urgencia || input.urgency);
const evaluationPrevious = text(input.evaluacion_previa || input.evaluation_previous);
const situation = text(input.situacion || input.situation);
const consultationReason = text(input.motivo_consulta || input.consultation_reason);
const source = text(input.origen || input.source || 'Landing odontología');
const page = text(input.pagina || input.page || 'landing');
const sentAt = input.fecha_envio ? new Date(input.fecha_envio) : new Date();

const phone = normalizePhone(phoneRaw);

if (!phone.phone_plus) {
  throw new Error('Teléfono inválido o vacío. No se puede crear el lead sin WhatsApp.');
}

let score = 0;
score += scoreTreatment(treatment);
score += scoreUrgency(urgency);
score += scoreEvaluation(evaluationPrevious);
score += scoreSituation(situation);
if (phone.phone_plus) score += 10;
if (name.split(' ').filter(Boolean).length >= 2) score += 5;

const classification = classify(score);
const action = nextAction(classification);

const notes = [
  source ? `Origen: ${source}` : '',
  page ? `Página: ${page}` : '',
  situation ? `Situación: ${situation}` : '',
  evaluationPrevious ? `Evaluación previa: ${evaluationPrevious}` : '',
].filter(Boolean).join(' | ');

const lead = {
  clinic_id: CLINIC_ID,
  name: name || 'Sin nombre',
  phone: phone.phone,
  phone_plus: phone.phone_plus,
  treatment: treatment || null,
  urgency: urgency || null,
  score,
  classification,
  status: 'Nuevo',
  situation: situation || null,
  evaluation_previous: evaluationPrevious || null,
  consultation_reason: consultationReason || null,
  estimated_value: estimateValue(treatment),
  next_action: action,
  next_followup_at: nextFollowupISO(classification, sentAt),
  contact_attempts: 0,
  whatsapp_link: buildWhatsappLink(phone.phone, name, treatment),
  source,
  page,
  notes: notes || null,
};

return {
  json: {
    lead,
    frontend_response_preview: {
      success: true,
      message: 'Datos enviados correctamente',
      classification,
      score,
    },
  },
};

const raw = $json.body ?? $json;
let lead = raw;

if (Array.isArray(raw)) {
  lead = raw[0] || {};
}

if (!lead.id && raw && typeof raw === 'object' && raw[0]) {
  lead = raw[0];
}

return {
  json: {
    success: true,
    message: 'Datos enviados correctamente',
    lead_id: lead.id || null,
    classification: lead.classification || 'Lead Medio',
    score: Number(lead.score || 0),
    status: lead.status || 'Nuevo',
  },
};
